// Stamps the submitted form values onto the PDF and wraps the result in an IPP Print-Job request.
const { PDFDocument, StandardFonts, rgb } = require('pdf-lib');

const cfg = $('Config').first().json;
const form = $('Print Form').first().json;

// --- 1. Insert text fields ---------------------------------------------------
const pdf = await PDFDocument.load(await this.helpers.getBinaryDataBuffer(0, 'data'));
const font = await pdf.embedFont(StandardFonts.Helvetica);
const pages = pdf.getPages();

for (const f of cfg.layout) {
  const text = String(form[f.field] ?? '').trim();
  if (!text) continue;
  const page = pages[(f.page ?? 1) - 1];
  if (!page) throw new Error(`Layout for "${f.field}" points to page ${f.page}, but the PDF has ${pages.length}`);
  const size = f.size ?? 11;
  // x / y are in PDF points (1/72 inch) measured from the bottom-left corner of the page
  page.drawText(text, { x: f.x, y: f.y, size, font, color: rgb(0, 0, 0), maxWidth: f.maxWidth, lineHeight: size * 1.25 });
}
const filled = Buffer.from(await pdf.save());

// --- 2. Build IPP Print-Job request (RFC 8011) ---------------------------------
const attr = (tag, name, value) => {
  const n = Buffer.from(name), v = Buffer.isBuffer(value) ? value : Buffer.from(String(value));
  const h = Buffer.alloc(3); h.writeUInt8(tag, 0); h.writeUInt16BE(n.length, 1);
  const l = Buffer.alloc(2); l.writeUInt16BE(v.length, 0);
  return Buffer.concat([h, n, l, v]);
};
const int = (n) => { const b = Buffer.alloc(4); b.writeInt32BE(n, 0); return b; };
const copies = Math.max(1, parseInt(cfg.copies ?? 1, 10) || 1);

const ipp = Buffer.concat([
  Buffer.from([0x02, 0x00, 0x00, 0x02]), int(1),            // IPP 2.0, Print-Job, request-id 1
  Buffer.from([0x01]),                                       // operation attributes
  attr(0x47, 'attributes-charset', 'utf-8'),
  attr(0x48, 'attributes-natural-language', 'en'),
  attr(0x45, 'printer-uri', cfg.printerUrl.replace(/^http/, 'ipp')),
  attr(0x42, 'requesting-user-name', 'n8n'),
  attr(0x42, 'job-name', cfg.jobName ?? 'n8n PDF form'),
  attr(0x49, 'document-format', 'application/pdf'),
  Buffer.from([0x02]),                                       // job attributes
  attr(0x21, 'copies', int(copies)),
  Buffer.from([0x03]),                                       // end of attributes
  filled,
]);

return [{
  json: { pages: pages.length, bytes: filled.length, copies },
  binary: {
    data: await this.helpers.prepareBinaryData(filled, 'filled-form.pdf', 'application/pdf'),
    ipp: await this.helpers.prepareBinaryData(ipp, 'print-job.ipp', 'application/ipp'),
  },
}];

// IPP response: bytes 2-3 are the status code; 0x0000-0x00FF = success
const res = await this.helpers.getBinaryDataBuffer(0, 'ippResponse');
const status = res.readUInt16BE(2);
if (status > 0x00ff) throw new Error(`Printer rejected the job (IPP status 0x${status.toString(16).padStart(4, '0')})`);
// job-id is an integer attribute (tag 0x21) named "job-id"
const i = res.indexOf(Buffer.from('job-id'));
const jobId = i > 0 ? res.readInt32BE(i + 6 + 2) : null;
return [{ json: { printed: true, ippStatus: status, jobId } }];
